  const flabel = el("p", { class: "ex-frame-label" }, "Read the frame first");
  const chips = el("div", { class: "ex-chips", role: "group", "aria-label": "Parts of the exhibit" });
  const explain = el("div", { class: "ex-explain", "aria-live": "polite", hidden: "" });

