    const b = el("button", { class: "chip ex-chip", type: "button", "data-for": p[0], "aria-pressed": "false" });
    add(b, el("span", { class: "ex-chip-n", "aria-hidden": "true" }, String(i + 1)), document.createTextNode(label));
